import {statusBadge} from '../application.mjs';import {channels} from './model.mjs';import {paymentLabels,fulfilmentLabels,isPaidOrder} from './lifecycle.mjs';
export function presentOrderDetail(doc,order){
 const root=doc.querySelector('#detail-content'),summary=doc.createElement('section'),nav=doc.createElement('nav');summary.id='order-summary';summary.className='admin-order-summary';summary.setAttribute('aria-label','Order summary');
 for(const text of [channels[order.channel]||order.channel,paymentLabels[order.paymentStatus]||order.paymentStatus,isPaidOrder(order)?fulfilmentLabels[order.fulfilmentStatus]||order.fulfilmentStatus:'Checkout attempt',new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(order.pricing.total/100)])summary.append(statusBadge(doc,text));
 nav.className='admin-order-sections';nav.setAttribute('aria-label','Order detail sections');const sections=[['Summary',summary]];for(const h of root.querySelectorAll(':scope > h3'))if(['Items','Pricing'].includes(h.textContent)){h.id='order-'+h.textContent.toLowerCase();sections.push([h.textContent,h]);}const communications=root.querySelector('.order-email-status');if(communications){communications.id='order-communications';sections.push(['Communications',communications]);}const dispatch=doc.querySelector('.dispatch-details');if(dispatch){dispatch.id='order-dispatch';sections.push(['Dispatch',dispatch]);const tracking=doc.createElement('p');tracking.textContent='Tracking reference: '+(order.dispatchDetails?.tracking_reference||'Not provided');dispatch.prepend(tracking);}const history=[...root.querySelectorAll(':scope > details')].find(d=>d.querySelector('summary')?.textContent==='Order history');if(history){history.id='order-history';sections.push(['History',history]);}for(const [label,target] of sections){const a=doc.createElement('a');a.href='#'+target.id;a.textContent=label;nav.append(a);}root.prepend(summary,nav);
}
